-- Migration: Insert 100 sample jewelry products
-- Timestamp: 20260317142000

DO $$
DECLARE
    cat_nhan UUID;
    cat_vong UUID;
    cat_day UUID;
    cat_bong UUID;
    cat_lac UUID;
BEGIN
    -- Fetch existing category IDs by slug
    SELECT id INTO cat_nhan FROM public.categories WHERE slug = 'nhan' OR name_vi ILIKE '%nhẫn%' OR name ILIKE '%ring%' LIMIT 1;
    SELECT id INTO cat_vong FROM public.categories WHERE slug = 'vong' OR name_vi ILIKE '%vòng%' OR name ILIKE '%bracelet%' LIMIT 1;
    SELECT id INTO cat_day FROM public.categories WHERE slug = 'day-chuyen' OR name_vi ILIKE '%dây%' OR name ILIKE '%necklace%' LIMIT 1;
    SELECT id INTO cat_bong FROM public.categories WHERE slug = 'bong-tai' OR name_vi ILIKE '%bông%' OR name ILIKE '%earring%' LIMIT 1;
    SELECT id INTO cat_lac FROM public.categories WHERE slug = 'lac' OR name_vi ILIKE '%lắc%' OR name ILIKE '%anklet%' LIMIT 1;

    -- Fallback: if any category not found, use the first available
    IF cat_nhan IS NULL THEN SELECT id INTO cat_nhan FROM public.categories ORDER BY sort_order LIMIT 1; END IF;
    IF cat_vong IS NULL THEN SELECT id INTO cat_vong FROM public.categories ORDER BY sort_order LIMIT 1; END IF;
    IF cat_day IS NULL THEN SELECT id INTO cat_day FROM public.categories ORDER BY sort_order LIMIT 1; END IF;
    IF cat_bong IS NULL THEN SELECT id INTO cat_bong FROM public.categories ORDER BY sort_order LIMIT 1; END IF;
    IF cat_lac IS NULL THEN SELECT id INTO cat_lac FROM public.categories ORDER BY sort_order LIMIT 1; END IF;

    -- =====================
    -- NHẪN (Rings) - 20 products
    -- =====================
    ON CONFLICT (slug) DO NOTHING;

    -- =====================
    -- VÒNG TAY (Bracelets) - 20 products
    -- =====================
    ON CONFLICT (slug) DO NOTHING;

    -- =====================
    -- DÂY CHUYỀN (Necklaces) - 20 products
    -- =====================
    ON CONFLICT (slug) DO NOTHING;

    -- =====================
    -- BÔNG TAI (Earrings) - 20 products
    -- =====================
    ON CONFLICT (slug) DO NOTHING;

    -- =====================
    -- LẮC CHÂN (Anklets) - 20 products
    -- =====================
    ON CONFLICT (slug) DO NOTHING;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Sample product insertion failed: %', SQLERRM;
END $$;
