    INSERT INTO public.products (id, category_id, name, name_vi, slug, description, description_vi, price, original_price, image_url, image_alt, sku, stock_quantity, is_active, is_new, is_best_seller, is_featured, material, weight_grams, tags)
    VALUES
    (gen_random_uuid(), cat_nhan, 'Diamond Solitaire Ring', 'Nhẫn Kim Cương Solitaire', 'nhan-kim-cuong-solitaire', 'Elegant solitaire diamond ring set in 18k white gold, perfect for engagements.', 'Nhẫn kim cương solitaire sang trọng được chế tác từ vàng trắng 18k, hoàn hảo cho lễ đính hôn.', 15800000, 18500000, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?w=600', 'Nhẫn kim cương solitaire vàng trắng 18k', 'NHN-001', 15, true, true, false, true, 'Vàng trắng 18k, Kim cương', 3.2, ARRAY['nhẫn', 'kim cương', 'đính hôn', 'vàng trắng']),
    (gen_random_uuid(), cat_nhan, 'Rose Gold Heart Ring', 'Nhẫn Vàng Hồng Hình Tim', 'nhan-vang-hong-hinh-tim', 'Romantic heart-shaped rose gold ring adorned with sparkling cubic zirconia.', 'Nhẫn vàng hồng hình trái tim lãng mạn được đính đá cubic zirconia lấp lánh.', 2850000, 3200000, 'https://images.unsplash.com/photo-1603561591411-07134e71a2a9?w=600', 'Nhẫn vàng hồng hình tim đính đá', 'NHN-002', 30, true, true, true, false, 'Vàng hồng 14k', 2.8, ARRAY['nhẫn', 'vàng hồng', 'hình tim', 'lãng mạn']),
    (gen_random_uuid(), cat_nhan, 'Sapphire Cluster Ring', 'Nhẫn Đá Sapphire Chùm', 'nhan-da-sapphire-chum', 'Stunning cluster ring featuring deep blue sapphires surrounded by diamonds.', 'Nhẫn chùm ấn tượng với đá sapphire xanh đậm được bao quanh bởi kim cương.', 9500000, 11000000, 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=600', 'Nhẫn đá sapphire chùm xanh đậm', 'NHN-003', 12, true, false, true, false, 'Vàng vàng 18k, Sapphire, Kim cương', 4.1, ARRAY['nhẫn', 'sapphire', 'chùm', 'xanh']),
    (gen_random_uuid(), cat_nhan, 'Gold Band Ring', 'Nhẫn Vàng Trơn', 'nhan-vang-tron', 'Classic plain gold band, timeless and versatile for everyday wear.', 'Nhẫn vàng trơn cổ điển, thanh lịch và linh hoạt cho việc đeo hàng ngày.', 4200000, NULL, 'https://images.unsplash.com/photo-1611591437281-460bfbe1220a?w=600', 'Nhẫn vàng trơn cổ điển', 'NHN-004', 50, true, false, true, false, 'Vàng vàng 18k', 5.0, ARRAY['nhẫn', 'vàng', 'trơn', 'cổ điển']),
    (gen_random_uuid(), cat_nhan, 'Emerald Cut Engagement Ring', 'Nhẫn Đính Hôn Cắt Emerald', 'nhan-dinh-hon-cat-emerald', 'Sophisticated emerald cut diamond engagement ring in platinum setting.', 'Nhẫn đính hôn kim cương cắt emerald tinh tế trong khung bạch kim.', 22500000, 26000000, 'https://images.unsplash.com/photo-1589674781759-c21c37956a44?w=600', 'Nhẫn đính hôn kim cương cắt emerald bạch kim', 'NHN-005', 8, true, true, false, true, 'Bạch kim, Kim cương', 4.5, ARRAY['nhẫn', 'đính hôn', 'kim cương', 'bạch kim']),
    (gen_random_uuid(), cat_nhan, 'Pearl Cocktail Ring', 'Nhẫn Ngọc Trai Cocktail', 'nhan-ngoc-trai-cocktail', 'Bold cocktail ring featuring a lustrous freshwater pearl centerpiece.', 'Nhẫn cocktail nổi bật với viên ngọc trai nước ngọt óng ánh ở trung tâm.', 3600000, 4100000, 'https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?w=600', 'Nhẫn ngọc trai cocktail sang trọng', 'NHN-006', 20, true, false, false, false, 'Bạc 925, Ngọc trai', 3.8, ARRAY['nhẫn', 'ngọc trai', 'cocktail']),
    (gen_random_uuid(), cat_nhan, 'Twisted Infinity Ring', 'Nhẫn Vô Cực Xoắn', 'nhan-vo-cuc-xoan', 'Delicate twisted infinity ring symbolizing eternal love and connection.', 'Nhẫn vô cực xoắn tinh tế tượng trưng cho tình yêu và sự kết nối vĩnh cửu.', 1950000, 2300000, 'https://images.unsplash.com/photo-1573408301185-9519f94816b5?w=600', 'Nhẫn vô cực xoắn tinh tế', 'NHN-007', 45, true, true, false, false, 'Bạc 925 mạ vàng', 2.1, ARRAY['nhẫn', 'vô cực', 'xoắn', 'tình yêu']),
    (gen_random_uuid(), cat_nhan, 'Ruby Halo Ring', 'Nhẫn Halo Đá Ruby', 'nhan-halo-da-ruby', 'Glamorous halo ring with a vivid red ruby surrounded by sparkling diamonds.', 'Nhẫn halo lộng lẫy với đá ruby đỏ rực được bao quanh bởi kim cương lấp lánh.', 12800000, 15000000, 'https://images.unsplash.com/photo-1602173574767-37ac01994b2a?w=600', 'Nhẫn halo đá ruby đỏ và kim cương', 'NHN-008', 10, true, false, true, true, 'Vàng vàng 18k, Ruby, Kim cương', 4.3, ARRAY['nhẫn', 'ruby', 'halo', 'đỏ']),
    (gen_random_uuid(), cat_nhan, 'Stackable Birthstone Ring', 'Nhẫn Đá Sinh Nhật Xếp Chồng', 'nhan-da-sinh-nhat-xep-chong', 'Minimalist stackable ring set with a colorful birthstone of your choice.', 'Nhẫn xếp chồng tối giản được đính đá sinh nhật màu sắc theo lựa chọn của bạn.', 1650000, NULL, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?w=600', 'Nhẫn đá sinh nhật xếp chồng tối giản', 'NHN-009', 60, true, true, false, false, 'Bạc 925', 1.8, ARRAY['nhẫn', 'đá sinh nhật', 'xếp chồng', 'tối giản']),
    (gen_random_uuid(), cat_nhan, 'Vintage Filigree Ring', 'Nhẫn Filigree Cổ Điển', 'nhan-filigree-co-dien', 'Intricate vintage-inspired filigree ring with antique gold finish.', 'Nhẫn filigree lấy cảm hứng cổ điển với hoàn thiện vàng cổ điển tinh xảo.', 3100000, 3700000, 'https://images.unsplash.com/photo-1506630448388-4e683c67ddb0?w=600', 'Nhẫn filigree cổ điển vàng antique', 'NHN-010', 18, true, false, false, false, 'Vàng vàng 14k', 3.5, ARRAY['nhẫn', 'filigree', 'cổ điển', 'vintage']),
    (gen_random_uuid(), cat_nhan, 'Moonstone Silver Ring', 'Nhẫn Bạc Đá Mặt Trăng', 'nhan-bac-da-mat-trang', 'Mystical moonstone ring in sterling silver with a glowing adularescence effect.', 'Nhẫn đá mặt trăng huyền bí bằng bạc sterling với hiệu ứng phát sáng adularescence.', 2200000, 2600000, 'https://images.unsplash.com/photo-1617038220319-276d3cfab638?w=600', 'Nhẫn bạc đá mặt trăng huyền bí', 'NHN-011', 25, true, true, false, false, 'Bạc 925, Đá mặt trăng', 2.9, ARRAY['nhẫn', 'đá mặt trăng', 'bạc', 'huyền bí']),
    (gen_random_uuid(), cat_nhan, 'Three Stone Diamond Ring', 'Nhẫn Ba Viên Kim Cương', 'nhan-ba-vien-kim-cuong', 'Symbolic three-stone diamond ring representing past, present, and future.', 'Nhẫn ba viên kim cương mang ý nghĩa tượng trưng cho quá khứ, hiện tại và tương lai.', 18500000, 21000000, 'https://images.unsplash.com/photo-1543294001-f7cd5d7fb516?w=600', 'Nhẫn ba viên kim cương vàng trắng', 'NHN-012', 7, true, false, true, true, 'Vàng trắng 18k, Kim cương', 4.8, ARRAY['nhẫn', 'kim cương', 'ba viên', 'đính hôn']),
    (gen_random_uuid(), cat_nhan, 'Opal Boho Ring', 'Nhẫn Boho Đá Opal', 'nhan-boho-da-opal', 'Free-spirited boho ring featuring a fire opal with rainbow color play.', 'Nhẫn boho phóng khoáng với đá opal lửa có sắc cầu vồng lung linh.', 2750000, 3200000, 'https://images.unsplash.com/photo-1598560917505-59a3ad559071?w=600', 'Nhẫn boho đá opal lửa cầu vồng', 'NHN-013', 22, true, true, false, false, 'Bạc 925, Đá opal', 2.6, ARRAY['nhẫn', 'opal', 'boho', 'cầu vồng']),
    (gen_random_uuid(), cat_nhan, 'Eternity Band', 'Nhẫn Eternity', 'nhan-eternity', 'Dazzling eternity band with diamonds set all the way around the band.', 'Nhẫn eternity lấp lánh với kim cương được đính xung quanh toàn bộ vòng nhẫn.', 8900000, 10500000, 'https://images.unsplash.com/photo-1596944924616-7b38e7cfac36?w=600', 'Nhẫn eternity kim cương toàn vòng', 'NHN-014', 14, true, false, true, false, 'Vàng trắng 18k, Kim cương', 3.9, ARRAY['nhẫn', 'eternity', 'kim cương', 'vàng trắng']),
    (gen_random_uuid(), cat_nhan, 'Amethyst Statement Ring', 'Nhẫn Đá Amethyst Nổi Bật', 'nhan-da-amethyst-noi-bat', 'Bold statement ring with a large oval amethyst in a gold prong setting.', 'Nhẫn nổi bật với đá amethyst hình bầu dục lớn trong khung vàng chấu.', 3400000, 3900000, 'https://images.unsplash.com/photo-1617038260897-41a1f14a8ca0?w=600', 'Nhẫn đá amethyst tím lớn nổi bật', 'NHN-015', 28, true, false, false, false, 'Vàng vàng 14k, Amethyst', 4.2, ARRAY['nhẫn', 'amethyst', 'tím', 'nổi bật']),
    (gen_random_uuid(), cat_nhan, 'Minimalist Thin Band', 'Nhẫn Mỏng Tối Giản', 'nhan-mong-toi-gian', 'Ultra-thin minimalist band ring, perfect for stacking or wearing alone.', 'Nhẫn mỏng tối giản, hoàn hảo để xếp chồng hoặc đeo riêng lẻ.', 980000, NULL, 'https://images.unsplash.com/photo-1561828995-aa79a2db86dd?w=600', 'Nhẫn mỏng tối giản bạc', 'NHN-016', 80, true, false, true, false, 'Bạc 925', 1.2, ARRAY['nhẫn', 'mỏng', 'tối giản', 'xếp chồng']),
    (gen_random_uuid(), cat_nhan, 'Aquamarine Oval Ring', 'Nhẫn Đá Aquamarine Bầu Dục', 'nhan-da-aquamarine-bau-duc', 'Serene aquamarine oval ring evoking the calm of the ocean in blue-green hues.', 'Nhẫn đá aquamarine hình bầu dục gợi lên sự bình yên của đại dương với sắc xanh lam.', 5600000, 6500000, 'https://images.unsplash.com/photo-1588444837495-c6cfeb53f32d?w=600', 'Nhẫn đá aquamarine xanh biển bầu dục', 'NHN-017', 16, true, true, false, false, 'Vàng trắng 14k, Aquamarine', 3.7, ARRAY['nhẫn', 'aquamarine', 'xanh biển', 'bầu dục']),
    (gen_random_uuid(), cat_nhan, 'Citrine Gold Ring', 'Nhẫn Vàng Đá Citrine', 'nhan-vang-da-citrine', 'Warm and sunny citrine ring in yellow gold, radiating positive energy.', 'Nhẫn đá citrine ấm áp và tươi sáng trong vàng vàng, tỏa ra năng lượng tích cực.', 4100000, 4800000, 'https://images.unsplash.com/photo-1573408301185-9519f94816b5?w=600', 'Nhẫn vàng đá citrine vàng cam', 'NHN-018', 20, true, false, false, false, 'Vàng vàng 14k, Citrine', 3.4, ARRAY['nhẫn', 'citrine', 'vàng', 'năng lượng']),
    (gen_random_uuid(), cat_nhan, 'Floral Diamond Ring', 'Nhẫn Kim Cương Hoa', 'nhan-kim-cuong-hoa', 'Whimsical floral ring with diamond petals blooming in white gold.', 'Nhẫn hoa mộng mơ với cánh hoa kim cương nở rộ trong vàng trắng.', 11200000, 13000000, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?w=600', 'Nhẫn kim cương hình hoa vàng trắng', 'NHN-019', 9, true, true, true, false, 'Vàng trắng 18k, Kim cương', 4.0, ARRAY['nhẫn', 'kim cương', 'hoa', 'vàng trắng']),
    (gen_random_uuid(), cat_nhan, 'Black Diamond Ring', 'Nhẫn Kim Cương Đen', 'nhan-kim-cuong-den', 'Edgy and modern black diamond ring set in black rhodium plated silver.', 'Nhẫn kim cương đen cá tính và hiện đại được đặt trong bạc mạ rhodium đen.', 6800000, 7900000, 'https://images.unsplash.com/photo-1603561591411-07134e71a2a9?w=600', 'Nhẫn kim cương đen rhodium đen', 'NHN-020', 13, true, true, false, false, 'Bạc 925 mạ rhodium đen, Kim cương đen', 3.6, ARRAY['nhẫn', 'kim cương đen', 'rhodium', 'cá tính'])
    INSERT INTO public.products (id, category_id, name, name_vi, slug, description, description_vi, price, original_price, image_url, image_alt, sku, stock_quantity, is_active, is_new, is_best_seller, is_featured, material, weight_grams, tags)
    VALUES
    (gen_random_uuid(), cat_vong, 'Tennis Bracelet', 'Vòng Tay Tennis Kim Cương', 'vong-tay-tennis-kim-cuong', 'Classic diamond tennis bracelet with a continuous line of brilliant-cut diamonds.', 'Vòng tay tennis kim cương cổ điển với hàng kim cương cắt brilliant liên tục.', 28500000, 33000000, 'https://images.unsplash.com/photo-1611591437281-460bfbe1220a?w=600', 'Vòng tay tennis kim cương cổ điển', 'VTT-001', 6, true, false, true, true, 'Vàng trắng 18k, Kim cương', 8.5, ARRAY['vòng tay', 'tennis', 'kim cương', 'cổ điển']),
    (gen_random_uuid(), cat_vong, 'Gold Bangle Bracelet', 'Vòng Tay Bangle Vàng', 'vong-tay-bangle-vang', 'Sleek solid gold bangle bracelet with a polished finish for everyday elegance.', 'Vòng tay bangle vàng đặc bóng với hoàn thiện đánh bóng cho sự thanh lịch hàng ngày.', 7800000, 9000000, 'https://images.unsplash.com/photo-1573408301185-9519f94816b5?w=600', 'Vòng tay bangle vàng đặc bóng', 'VTT-002', 25, true, false, true, false, 'Vàng vàng 18k', 12.0, ARRAY['vòng tay', 'bangle', 'vàng', 'thanh lịch']),
    (gen_random_uuid(), cat_vong, 'Pearl Strand Bracelet', 'Vòng Tay Chuỗi Ngọc Trai', 'vong-tay-chuoi-ngoc-trai', 'Elegant freshwater pearl strand bracelet with a gold lobster clasp.', 'Vòng tay chuỗi ngọc trai nước ngọt thanh lịch với khóa tôm vàng.', 4500000, 5200000, 'https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?w=600', 'Vòng tay chuỗi ngọc trai nước ngọt', 'VTT-003', 20, true, true, false, false, 'Ngọc trai, Vàng 14k', 6.2, ARRAY['vòng tay', 'ngọc trai', 'chuỗi', 'thanh lịch']),
    (gen_random_uuid(), cat_vong, 'Charm Bracelet', 'Vòng Tay Charm', 'vong-tay-charm', 'Playful charm bracelet with a mix of gold and silver charms for personalization.', 'Vòng tay charm vui nhộn với hỗn hợp charm vàng và bạc để cá nhân hóa.', 3200000, 3800000, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?w=600', 'Vòng tay charm vàng bạc cá nhân hóa', 'VTT-004', 35, true, true, true, false, 'Bạc 925, Vàng 14k', 5.8, ARRAY['vòng tay', 'charm', 'cá nhân hóa', 'vui nhộn']),
    (gen_random_uuid(), cat_vong, 'Cuff Bracelet', 'Vòng Tay Cuff Bạc', 'vong-tay-cuff-bac', 'Bold open cuff bracelet in sterling silver with hammered texture.', 'Vòng tay cuff mở mạnh mẽ bằng bạc sterling với kết cấu búa.', 2100000, 2500000, 'https://images.unsplash.com/photo-1506630448388-4e683c67ddb0?w=600', 'Vòng tay cuff bạc kết cấu búa', 'VTT-005', 30, true, false, false, false, 'Bạc 925', 9.5, ARRAY['vòng tay', 'cuff', 'bạc', 'búa']),
    (gen_random_uuid(), cat_vong, 'Rose Gold Chain Bracelet', 'Vòng Tay Dây Chuyền Vàng Hồng', 'vong-tay-day-chuyen-vang-hong', 'Delicate rose gold chain bracelet with a heart-shaped lobster clasp.', 'Vòng tay dây chuyền vàng hồng tinh tế với khóa tôm hình trái tim.', 1850000, 2200000, 'https://images.unsplash.com/photo-1617038220319-276d3cfab638?w=600', 'Vòng tay dây chuyền vàng hồng tinh tế', 'VTT-006', 45, true, true, false, false, 'Vàng hồng 14k', 3.1, ARRAY['vòng tay', 'dây chuyền', 'vàng hồng', 'tinh tế']),
    (gen_random_uuid(), cat_vong, 'Sapphire Link Bracelet', 'Vòng Tay Mắt Xích Sapphire', 'vong-tay-mat-xich-sapphire', 'Luxurious link bracelet alternating sapphires and diamonds in white gold.', 'Vòng tay mắt xích sang trọng xen kẽ sapphire và kim cương trong vàng trắng.', 16500000, 19000000, 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=600', 'Vòng tay mắt xích sapphire kim cương vàng trắng', 'VTT-007', 8, true, false, true, true, 'Vàng trắng 18k, Sapphire, Kim cương', 10.2, ARRAY['vòng tay', 'sapphire', 'kim cương', 'mắt xích']),
    (gen_random_uuid(), cat_vong, 'Beaded Gemstone Bracelet', 'Vòng Tay Đá Quý Hạt', 'vong-tay-da-quy-hat', 'Colorful beaded bracelet featuring natural gemstones for healing energy.', 'Vòng tay hạt đá quý tự nhiên đầy màu sắc mang năng lượng chữa lành.', 1200000, 1500000, 'https://images.unsplash.com/photo-1598560917505-59a3ad559071?w=600', 'Vòng tay hạt đá quý tự nhiên màu sắc', 'VTT-008', 55, true, false, false, false, 'Đá quý tự nhiên', 7.3, ARRAY['vòng tay', 'đá quý', 'hạt', 'năng lượng']),
    (gen_random_uuid(), cat_vong, 'Diamond Pave Bracelet', 'Vòng Tay Pave Kim Cương', 'vong-tay-pave-kim-cuong', 'Glamorous pave diamond bracelet with hundreds of tiny diamonds set closely together.', 'Vòng tay pave kim cương lộng lẫy với hàng trăm viên kim cương nhỏ được đặt sát nhau.', 35000000, 40000000, 'https://images.unsplash.com/photo-1589674781759-c21c37956a44?w=600', 'Vòng tay pave kim cương lộng lẫy', 'VTT-009', 4, true, false, true, true, 'Vàng trắng 18k, Kim cương', 9.8, ARRAY['vòng tay', 'pave', 'kim cương', 'lộng lẫy']),
    (gen_random_uuid(), cat_vong, 'Leather Wrap Bracelet', 'Vòng Tay Da Quấn', 'vong-tay-da-quan', 'Bohemian leather wrap bracelet with gold accents and turquoise stones.', 'Vòng tay da quấn phong cách bohemian với điểm nhấn vàng và đá turquoise.', 850000, 1100000, 'https://images.unsplash.com/photo-1596944924616-7b38e7cfac36?w=600', 'Vòng tay da quấn bohemian vàng turquoise', 'VTT-010', 40, true, true, false, false, 'Da, Vàng 14k, Turquoise', 4.5, ARRAY['vòng tay', 'da', 'quấn', 'bohemian']),
    (gen_random_uuid(), cat_vong, 'Infinity Bracelet', 'Vòng Tay Vô Cực', 'vong-tay-vo-cuc', 'Meaningful infinity symbol bracelet in sterling silver with cubic zirconia.', 'Vòng tay biểu tượng vô cực ý nghĩa bằng bạc sterling với đá cubic zirconia.', 1450000, 1750000, 'https://images.unsplash.com/photo-1543294001-f7cd5d7fb516?w=600', 'Vòng tay vô cực bạc cubic zirconia', 'VTT-011', 50, true, true, true, false, 'Bạc 925, Cubic Zirconia', 4.0, ARRAY['vòng tay', 'vô cực', 'bạc', 'ý nghĩa']),
